insert into disclosure_frameworks (id, key, name, description) values
  ('7ed28cb0-3b07-4d7c-bb46-af63d24bb0d7', 'cdp', 'CDP 気候変動質問書（架空縮小版）', '正式質問書ではありません。年度 Version 差分の再現を目的とした架空マスターです。'),
  ('488465f1-0a2a-4ff9-80ab-098ca5c9d891', 'ssbj', 'SSBJ サステナビリティ開示基準', 'サステナビリティ基準委員会（SSBJ）公表の正式基準に基づく開示要求マスター。テーマ別基準第1号（一般開示基準）・第2号（気候関連開示基準）のコア・コンテンツ（2026年3月13日改正）と実務対応基準第1号（2026年6月11日公表）を収録。原文は SSBJ の転載許可を得て収録している。'),
  ('08d77074-96b4-4c77-b670-6f7fb405b91d', 'csrd', 'CSRD / ESRS 開示項目（架空縮小版）', '正式な ESRS 全量ではありません。初年度ギャップ分析を目的とした架空縮小マスターです。');
