insert into assurance_procedures (id, engagement_id, assurance_firm_id, code, title, description, category, required, sort_order, created_at, updated_at, created_by, updated_by) values
  ('d2ba8c15-b890-47ef-8a52-125b491003b9', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-01', '母集団の完全性確認', '対象期間・対象組織のデータが漏れなく母集団に含まれていることを、組織マスターおよび報告期間設定と突合して確かめる。', 'completeness', true, 0, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
  ('d2ba8d15-b890-49a2-9568-822d59686417', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-02', '原資料との照合', 'サンプルの値を Evidence（請求書・計測記録等）と照合し、金額・数量・期間の一致を確かめる。', 'accuracy', true, 1, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
  ('d2ba8e15-b890-4b55-9d57-77720da07075', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-03', '再計算', '算定式、活動量、排出係数、単位換算を用いて独立に再計算し、記録値との差異を確かめる。', 'recalculation', true, 2, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
  ('d2ba8715-b890-4f70-ba29-11d2153ea59f', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-04', '期間帰属（カットオフ）の確認', 'Evidence の対象期間が報告対象期間に帰属していることを確かめる。', 'cutoff', true, 3, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
  ('d2ba8815-b890-4123-9ce5-5fef98f47a61', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-05', '単位・換算の妥当性', '報告単位、換算係数、係数年度が指標定義と整合していることを確かめる。', 'accuracy', true, 4, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
  ('d2ba8915-b890-42d6-b702-701e6821bcc7', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-06', '担当者への質問', '算定方法の変更、見積り、除外の理由について担当者へ質問し、回答を記録する。', 'inquiry', false, 5, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
  ('d2ba8a15-b890-4489-9e72-cb49a9b24075', 'df8c998b-6875-4c9f-8975-335e3b8a2acb', '65db1d85-8a3d-4c97-ab96-80df81153d91', 'P-07', '承認証跡の閲覧', '企業側のレビュー・承認が権限者により実施されていることを閲覧により確かめる。', 'inspection', false, 6, '2026-05-09T03:00:00.000Z', '2026-05-09T03:00:00.000Z', 'b509ba85-85f8-4401-9092-5c700cc1cc0d', 'b509ba85-85f8-4401-9092-5c700cc1cc0d'),
